import React, { useState } from 'react';
import './WelcomeModal.css';
import welcomeStartModel from '../assets/welcomesstartmodel.svg';

const WelcomeModal = ({ isOpen, onClose }) => {
  const [prompt, setPrompt] = useState('');

  if (!isOpen) return null;

  return (
    <div className="modal-overlay">
      <div className="modal-content">
        <h2 className="start-header">Start</h2>

        <p className="welcome-text">
          Welcome to Agent QA! You can start your journey with QA Agent now to get your GUI & API testing done!
        </p>

        <div className="image-container">
          <img src={welcomeStartModel} alt="Welcome Start Model" className="welcome-image" />
        </div>

        <div className="prompt-container">
          <div className="prompt-label">Enter your prompt</div>
          <div className="input-wrapper">
            <input 
              type="text" 
              placeholder="To start new chat for generating test cases"
              value={prompt}
              onChange={(e) => setPrompt(e.target.value)}
              className="prompt-input"
            />
            <div className="input-helper-text">
              To start new chat for generating test cases
            </div>
          </div>
          <button className="next-button">
            Next <span className="arrow">→</span>
          </button>
        </div>
      </div>
    </div>
  );
};

export default WelcomeModal;
